package com.farmconnect.service.impl; import com.farmconnect.entity.Product; import com.farmconnect.repository.ProductRepository; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import java.math.BigDecimal; import java.math.RoundingMode; import java.util.List; @Service @RequiredArgsConstructor public class PricePredictionServiceImpl { private final ProductRepository productRepository; public PricePrediction predict( Product.Category category, Product.Unit unit, boolean isOrganic) { List<Product> similar = productRepository .findByCategoryAndAvailabilityTrue(category) .stream() .filter(p -> p.getUnit() == unit) .filter(p -> p.getPrice() != null) .toList(); if (similar.isEmpty()) { return new PricePrediction( null, "Not enough market data yet for this category/unit to suggest a price." ); } BigDecimal total = similar.stream() .map(Product::getPrice) .reduce(BigDecimal.ZERO, BigDecimal::add); long count = similar.size(); if (count == 0) { return new PricePrediction( null, "Not enough market data yet for this category/unit to suggest a price." ); } BigDecimal average = total.divide( BigDecimal.valueOf(count), 2, RoundingMode.HALF_UP ); BigDecimal suggestedPrice; if (isOrganic) { suggestedPrice = average .multiply(BigDecimal.valueOf(1.15)) .setScale(2, RoundingMode.HALF_UP); } else { suggestedPrice = average.setScale( 2, RoundingMode.HALF_UP ); } String explanation = "Based on the average listed price of " + count + " similar " + category + " products (" + unit + ")" + (isOrganic ? " with an organic premium applied." : "."); return new PricePrediction( suggestedPrice, explanation ); } public record PricePrediction( BigDecimal suggestedPrice, String explanation ) { } }